import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline CUDA code for a custom ReLU operator
relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void relu_kernel(const float* in, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        out[idx] = val > 0.0f ? val : 0.0f;
    }
}

torch::Tensor relu_cuda(torch::Tensor input) {
    auto size = input.numel();
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    relu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        out.data_ptr<float>(),
        (int)size
    );

    return out;
}
"""

relu_cpp_source = r"torch::Tensor relu_cuda(torch::Tensor input);"

# Compile the inline custom ReLU operator
relu_module = load_inline(
    name="custom_relu",
    cpp_sources=relu_cpp_source,
    cuda_sources=relu_source,
    functions=["relu_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, num_classes):
        """
        Optimized LeNet-5 architecture with a custom CUDA-based ReLU.
        """
        super(ModelNew, self).__init__()

        # Convolutional layers
        self.conv1 = nn.Conv2d(in_channels=1, out_channels=6, kernel_size=5, stride=1)
        self.conv2 = nn.Conv2d(in_channels=6, out_channels=16, kernel_size=5, stride=1)

        # Fully connected layers
        self.fc1 = nn.Linear(in_features=16*5*5, out_features=120)
        self.fc2 = nn.Linear(in_features=120, out_features=84)
        self.fc3 = nn.Linear(in_features=84, out_features=num_classes)

        # Reference to custom ReLU extension
        self.custom_relu = relu_module.relu_cuda

    def forward(self, x):
        # conv1 + custom relu + max pool
        x = self.conv1(x)
        x = self.custom_relu(x)
        x = F.max_pool2d(x, kernel_size=2, stride=2)

        # conv2 + custom relu + max pool
        x = self.conv2(x)
        x = self.custom_relu(x)
        x = F.max_pool2d(x, kernel_size=2, stride=2)

        # Flatten
        x = x.view(-1, 16*5*5)

        # fc1 + custom relu
        x = self.fc1(x)
        x = self.custom_relu(x)

        # fc2 + custom relu
        x = self.fc2(x)
        x = self.custom_relu(x)

        # final fc
        x = self.fc3(x)
        return x

def get_inputs():
    # Return the inputs for a forward pass
    return [torch.randn(1, 1, 32, 32).cuda()]

def get_init_inputs():
    # Return initialization arguments for the model
    return [10]
